extends "res://hud2d-project-runtime.gd"
var gui_button: Button
var gui_layer: CanvasLayer
var gui_count := 0
var sample_tick := 0
const NAV_BINDINGS = {"dddddddd-dddd-4ddd-8ddd-dddddddddddd":"99999999-9999-4999-8999-999999999991","12345678-1234-4234-8234-123456789abd":"12345678-1234-4234-8234-123456789ac3","00000385-1111-4111-8111-111111111111":"00000388-1111-4111-8111-111111111111"}
func _ready() -> void:
	super._ready()
	gui_layer = CanvasLayer.new()
	gui_layer.layer = 2
	gui_button = Button.new()
	gui_button.text = "Test GUI consumes Enter / Space"
	gui_button.position = Vector2(280, 80)
	gui_button.size = Vector2(320, 48)
	gui_button.gui_input.connect(_consume_gui)
	gui_layer.add_child(gui_button)
	add_child(gui_layer)
	gui_button.grab_focus()
func _consume_gui(event: InputEvent) -> void:
	if event.is_action("menu_start"):
		if event.is_pressed() and not event.is_echo():
			gui_count += 1
		gui_button.accept_event()
		print("NAV_GUI_HANDLED:" + JSON.stringify({"pressed":event.is_pressed(),"handled":get_viewport().is_input_handled()}))
func _input(event: InputEvent) -> void:
	if event is InputEventKey:
		var nav = current.find_child("behavior_" + NAV_BINDINGS[current_scene].replace("-", "_"), true, false) if current != null else null
		print("NAV_INPUT:" + JSON.stringify({"key":event.physical_keycode,"pressed":event.pressed,"echo":event.echo,"sceneId":current_scene,"down":Input.is_action_pressed("menu_start"),"guiFocused":gui_button.has_focus() if gui_button != null else false,"armed":nav.get("_armed") if nav != null and nav.has_method("_on_focus_entered") else false,"candidate":nav.get("_candidate_event_id") if nav != null and nav.has_method("_on_focus_entered") else 0}))
	if event is InputEventKey and event.pressed and not event.echo and event.physical_keycode == KEY_F8:
		gui_button.hide()
		get_viewport().set_input_as_handled()
func enter_scene(scene_id: String) -> void:
	super.enter_scene(scene_id)
	call_deferred("capture_visit", visit_index, scene_id)
func leave_scene(reason: String, next_scene: String = "") -> void:
	var nav = current.find_child("behavior_" + NAV_BINDINGS[current_scene].replace("-", "_"), true, false)
	var retained_port = nav.get_meta("viento_project")
	var old_node = weakref(nav)
	var visit = visit_index
	super.leave_scene(reason, next_scene)
	var refused: bool = not retained_port.request_scene("dddddddd-dddd-4ddd-8ddd-dddddddddddd")
	print("NAV_STALE_PORT:" + JSON.stringify({"visit":visit,"refused":refused,"behaviorFreed":old_node.get_ref() == null}))
	if not refused or old_node.get_ref() != null:
		push_error("Stale navigation visit retained authority")
func capture_visit(visit: int, scene_id: String) -> void:
	await RenderingServer.frame_post_draw
	if current != null and visit_index == visit and current_scene == scene_id and visit <= 3:
		get_viewport().get_texture().get_image().save_png("/home/chiharukiryu/cdev/viento-studio/docs/test-results/scene-navigation/native-final-2026-11-13/offline-keyboard" + "/visit-" + str(visit) + ".png")
func _process(delta: float) -> void:
	super._process(delta)
	if current == null:
		return
	sample_tick += 1
	if sample_tick % 3 != 0:
		return
	var behavior = current.find_child("behavior_" + NAV_BINDINGS[current_scene].replace("-", "_"), true, false)
	var action: bool = behavior.has_method("_on_focus_entered")
	var hud = current.get_node_or_null("VientoHUD2D")
	print("NAV_SAMPLE:" + JSON.stringify({"sceneId":current_scene,"visit":visit_index,"actionDown":Input.is_action_pressed("menu_start"),"focused":get_window().has_focus(),"armed":behavior.get("_armed") if action else false,"accepted":behavior.get("_accepted"),"guiCount":gui_count,"guiOpen":gui_button.visible if gui_button != null else false,"hudId":hud.get_instance_id() if hud != null else 0,"hudText":hud.rows[0].label.text if hud != null else ""}, "", true, true))

sources.content:
extends Node

@export var action_name: String = "ui_accept"
@export var target_scene_id: String = ""
var _project
var _active := false
var _armed := false
var _candidate_event_id: int = 0
var _accepted := false
var _window: Window
var _focused := false

func _object_valid(value) -> bool:
	return typeof(value) == TYPE_OBJECT and is_instance_valid(value)

func _uuid(value: String) -> bool:
	var pattern := RegEx.new()
	pattern.compile("^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$")
	return value.length() == 36 and pattern.search(value) != null

func _ready() -> void:
	_deactivate()
	if action_name.is_empty() or not _uuid(target_scene_id):
		_fail("Choose an existing input action and a target member scene UUID.")
		return
	if not has_meta("viento_project"):
		_fail("Bind this script in a project assembly run.")
		return
	var project = get_meta("viento_project")
	if not _object_valid(project) or not project.has_method("request_scene"):
		_fail("The visit-bound scene request port is unavailable.")
		return
	if not InputMap.has_action(action_name):
